<script>
 import {Sparkles,ArrowUpRight} from 'lucide-svelte';import {studio,asset,run,updateProject,save,notify,referencePreview,goSettings,importImages} from '../studio.svelte';import {api,clone} from '../api';import {estimate,money} from '../cost';
 let prompt=$state(''),modelId=$state(''),resolution=$state('1K'),ratio=$state('1:1'),approved=$state(false),inputTokens=$state(1300),outputTokens=$state(300),configured=$state(false);
 let models=$derived(studio.catalog?.models||[]),model=$derived(models.find(m=>m.id===modelId)||models[0]);
 $effect(()=>{if(model){if(!modelId)modelId=model.id;if(!model.resolutions.includes(resolution))resolution=model.resolutions[0];if(!model.ratios.includes(ratio))ratio=model.ratios[0];}});
 $effect(()=>{if(studio.mode!=='generate')return;api('credential_status').then(v=>configured=v).catch(()=>{});});
 $effect(()=>{prompt;modelId;resolution;ratio;inputTokens;outputTokens;studio.aid;JSON.stringify(studio.draft);approved=false;});
 let cost=$derived(model?estimate(model,resolution,inputTokens,outputTokens):null);
 async function generate(){await run('Generating',async()=>{await save([studio.aid]);const result=await api('generate',{projectId:studio.pid,assetId:studio.aid,edit:clone(studio.draft),prompt,model:model.id,resolution,ratio,approved,estimatedInputTokens:inputTokens,estimatedOutputTokens:outputTokens});updateProject(result.project);approved=false;studio.modal={type:'review',version:asset().versions.find(v=>v.id===result.versionId)};notify('Generation ready for review');});}
</script>
{#if !asset()}<div class="workflow-panel"><div class="empty"><h2>Select a reference image</h2><div class="button-row"><button class="primary" onclick={()=>importImages(false)}>Import images</button><button class="line-button" onclick={()=>{studio.mode='edit';studio.view='projects';}}>Open projects</button></div></div></div>{:else}<div class="workflow-panel generation-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>Generate</h1><span>Current image · Google</span></div><div class="generation-layout"><div class="generation-reference"><img src={referencePreview()} alt="Reference"/><span>{asset()?.name}</span><div class="generation-history">{#each [...(asset()?.versions||[])].filter(v=>v.kind==='generated').reverse() as v}<button class="line-button" onclick={()=>studio.modal={type:'review',version:v}}>{new Date(v.createdAt*1000).toLocaleDateString()}<ArrowUpRight size={13}/></button>{/each}</div></div><div class="generation-form"><label>Prompt<textarea aria-label="Generation prompt" bind:value={prompt} placeholder="Describe the image you want to create." rows="6"></textarea></label><label>Model<select aria-label="Generation model" bind:value={modelId}>{#each models as m}<option value={m.id}>{m.name}</option>{/each}</select></label><div class="field-grid"><label>Resolution<select bind:value={resolution}>{#each model?.resolutions||[] as r}<option>{r}</option>{/each}</select></label><label>Ratio<select bind:value={ratio}>{#each model?.ratios||[] as r}<option>{r}</option>{/each}</select></label></div><details><summary>Usage estimate</summary><div class="field-grid"><label>Input tokens<input type="number" min="0" bind:value={inputTokens}/></label><label>Text / thinking tokens<input type="number" min="0" bind:value={outputTokens}/></label></div></details><div class="cost-line"><span>Estimated cost</span><b>{money(cost,studio.currency,studio.exchangeRate)}</b></div><label class="checkbox-label"><input type="checkbox" bind:checked={approved}/>Approve this paid request</label><button class="primary full" disabled={!!studio.busy||!prompt.trim()||!approved||!configured||!asset()} onclick={generate}><Sparkles size={16}/>Generate</button>{#if !configured}<button class="text-button" onclick={()=>goSettings('generate')}>Connect Google in Settings<ArrowUpRight size={13}/></button>{/if}</div></div></div>
{/if}
